const f = $('Form Trigger').first().json;
const tools = String(f.tools || '').split('\n').map(s=>s.trim()).filter(Boolean)
  .map(line => { const p = line.split('|').map(x=>x.trim()); return { n: p[0]||p[1]||'Tool', slug: p[1]||'', desc: p[2]||'' }; });
const name = f.name || 'My Site';
const wf = `# 线框图：${name}
## 页面结构
1. Header / 导航（Logo、工具、定价、博客、语言）
2. Hero（标题、定位、主 CTA「免费开始」）
3. 工具网格（${tools.length||'N'} 个工具卡片，hover 预览）
4. 使用步骤 How-it-works（3 步）
5. 定价 / 变现（${f.monetization||'ads'}）
6. FAQ（结构化数据）
7. Footer（合规链接）`;
return [{ json: { wireframe: wf } }];

const f = $('Form Trigger').first().json;
const aud = String(f.audience||'').toLowerCase();
const mon = String(f.monetization||'ads');
let style='minimal', rationale='通用简洁风格，适配大多数工具站', palette='#5b34e6 / #f8fafc';
if (/child|kid|儿童|玩|fun|game/.test(aud)) { style='playful'; rationale='目标含儿童/娱乐，用活泼配色与圆角'; palette='#8b6ef0 / #8b6ef0'; }
else if (/financ|crypto|投资|money|bank/.test(aud)) { style='midnight'; rationale='金融/严肃场景，深色高端感'; palette='#4a25c9 / #5b34e6'; }
else if (/creativ|design|艺术|portfolio/.test(aud)) { style='bold'; rationale='创意向，强对比大胆视觉'; palette='#5b34e6 / #5b34e6'; }
else if (/saas|professional|企业|business|团队/.test(aud)) { style='glassmorphism'; rationale='SaaS/企业，玻璃拟态显专业'; palette='#8b6ef0 / #fffdf9'; }
if ((mon==='subscription'||mon==='freemium') && style==='minimal') style='glassmorphism';
return [{ json: { recommendedStyle: style, rationale, palette, style } }];

const r = $('HTTP: AI Style').first().json;
let style = $('Code: Recommend Style').first().json.recommendedStyle;
let rationale = 'AI 辅助建议';
try {
  const content = (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '';
  const m = content.match(/\{[\s\S]*\}/);
  if (m) { const j = JSON.parse(m[0]); if (j.style) style = j.style; if (j.rationale) rationale = j.rationale; }
} catch (e) {}
return [{ json: { style, recommendedStyle: style, rationale, aiUsed: true } }];

const f = $('Form Trigger').first().json;
const c = $('Form: Confirm UI Style').first().json;
const style = c.style || 'minimal';
const slugify = s => s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'') || 'site';
const tools = String(f.tools||'').split('\n').map(s=>s.trim()).filter(Boolean).map(line=>{
  const p = line.split('|').map(x=>x.trim());
  const slug = slugify(p[1]||p[0]||'tool');
  return { name: p[0]||p[1]||'Tool', slug, desc: p[2]||'', icon:'⚙️', keywords:[] };
});
const themeMap = { minimal:'indigo', bold:'sunset', playful:'emerald', glassmorphism:'ocean', midnight:'midnight' };
const slug = f.slug ? slugify(f.slug) : slugify(f.name||'site');
const spec = {
  name: f.name, slug, domain: f.domain || '', tagline: f.tagline||'',
  lang: f.language || 'en', theme: themeMap[style] || 'ocean',
  audience: String(f.audience||'').split(',').map(s=>s.trim()).filter(Boolean),
  keywords: String(f.keywords||'').split(',').map(s=>s.trim()).filter(Boolean),
  tools,
  monetization: { model: f.monetization||'ads', currency: f.currency||'USD' },
  legal: { email: '', jurisdiction: 'global' },
  deploy: { target: 'none' }
};
const outDir = 'C:/Users/nathon.wang/WorkBuddy/2026-10-26-00-00-50/n8n-indie-builder/sites/' + slug;
const agentWorkDir = '/home/node/sites/' + slug;
const brief = [
  '# 站点实现简报 (AGENTS.md)',
  '',
  '站点名称: ' + f.name,
  '一句话定位: ' + (f.tagline||'(未填)'),
  '语言: ' + (f.language||'en'),
  '目标用户: ' + (f.audience||'(未填)'),
  '关键词(SEO): ' + (f.keywords||''),
  '视觉风格: ' + style,
  '变现模式: ' + (f.monetization||'ads'),
  '',
  '## 任务',
  '1. 阅读 src/pages 下的占位工具页（标记“当前是占位实现”的页面）。',
  '2. 为每个工具实现**纯前端、可运行**的交互逻辑：不请求任何外部网络、不上传用户数据。',
  '3. 如需数据，使用浏览器端计算（如字符串处理、本地加解密、随机生成等）。',
  '4. 保证 SEO（语义化标签、meta、结构化数据）、响应式、可访问性。',
  '5. 不要改动工程骨架与构建配置，只补全工具页逻辑。',
  '',
  '## 工具清单',
].concat(tools.map(t => '- ' + t.name + (t.desc? '：'+t.desc : ''))).join('\n')
 + (f.agentExtra ? '\n\n## 用户额外指令\n' + f.agentExtra : '');
return [{ json: { spec, outDir, agentWorkDir, slug, style, brief } }];

const f = $('Form Trigger').first().json;
const b = $('Code: Build Spec').first().json;
const provider = String(f.agentProvider || 'claude').toLowerCase();
const wd = b.agentWorkDir;
const model = String(f.agentModel || '').trim();
const baseUrl = String(f.modelBaseUrl || '').trim();
const prompt = 'Read AGENTS.md in the current directory and implement every tool and page it describes. Produce production-quality Astro + TypeScript. Keep ALL logic client-side only: no external network requests, no data upload. Make the site SEO-friendly and responsive. After editing, if package.json has a build or check script, run it to verify. Summarize what you changed.';
// 工作目录由 bridge 的 /run 通过 cwd 传入，这里不再拼 cd
let cmd;
if (provider === 'codex') {
  cmd = "codex exec '" + prompt + "' -s workspace-write -a never -m " + (model || 'gpt-5-codex');
} else if (provider === 'opencode') {
  cmd = "opencode run '" + prompt + "' --dir " + wd + ' --auto --format json' + (model ? ' -m ' + model : '');
} else {
  cmd = "claude -p '" + prompt + "' --allowedTools 'Edit,Write,Read,Bash,Grep,Glob,MultiEdit' --dangerously-skip-permissions --model " + (model || 'sonnet') + ' --output-format text';
}
// 自定义模型地址：通过 /run 的 env 注入（Claude -> ANTHROPIC_BASE_URL；Codex/OpenCode -> OPENAI_BASE_URL）
const agentEnv = {};
if (baseUrl) {
  if (provider === 'claude') agentEnv.ANTHROPIC_BASE_URL = baseUrl;
  else { agentEnv.OPENAI_BASE_URL = baseUrl; agentEnv.ANTHROPIC_BASE_URL = baseUrl; }
}
return [{ json: { agentCommand: cmd, provider: provider, agentWorkDir: wd, agentEnv } }];

const f = $('Form Trigger').first().json;
const gen = $('HTTP: /generate').first().json;
const build = $('Code: Build Spec').first().json;
const provider = f.agentProvider || 'claude';
// 只有被路由选中的 agent 分支真正执行，用 .all() 安全取值，避免未执行节点报错
let agentOut = '';
const cli = $('HTTP: Agent Run').all();
const br = $('HTTP: /complete (bridge)').all();
if (cli.length) agentOut = cli[0].json.stdout || '';
else if (br.length) agentOut = JSON.stringify(br[0].json.report || '');
const snippet = (typeof agentOut === 'string' ? agentOut : JSON.stringify(agentOut)).slice(0, 1500);
return [{ json: {
  name: f.name, slug: gen.slug || build.slug,
  style: $('Form: Confirm UI Style').first().json.style,
  dir: gen.dir || build.outDir,
  agentWorkDir: build.agentWorkDir,
  provider,
  status: (gen.ok ? '脚手架+Agent 完成' : '脚手架失败'),
  agentLog: snippet
} }];

